using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ApiTools
{
    [McpServerTool, Description("Fetches a post by ID from the external API.")]
    public static async Task<string> GetPost(
        IHttpClientFactory httpClientFactory,
        [Description("The numeric post ID to retrieve.")] int id)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var post = await client.GetFromJsonAsync<JsonElement>($"/posts/{id}");
        return post.ToString();
    }
}

using System.ComponentModel;
using ModelContextProtocol;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a prompt that asks the model to summarize text.")]
    public static ChatMessage Summarize(
        [Description("The text content to summarize.")] string text)
    {
        return new ChatMessage(
            ChatRole.User,
            $"Please provide a concise summary of the following text:\n\n{text}");
    }
}

